// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;

    function setUp() public { c = new FlashGovernanceArbiter(address(new __InvMutHandleStub())); }

    function testFuzz_property(uint256 amount, uint256 unlockTime, address target) public {
        vm.assume(amount > 0);
        vm.assume(target != address(0) && target != address(c));
        unlockTime = bound(unlockTime, 0, 365 days);

        address actor = address(0xA11CE);
        address asset = address(new __InvMutHandleStub());

        // configured == false, so onlySuccessfulProposal passes for anyone.
        address[] memory gs = new address[](1);
        gs[0] = actor;
        bool[] memory bs = new bool[](1);
        bs[0] = true;
        c.setGoverned(gs, bs);

        c.configureFlashGovernance(asset, amount, unlockTime, false);

        // Create the pending flash decision.
        vm.prank(actor);
        c.assertGovernanceApproved(actor, target, true);

        // The entry must exist before withdrawal.
        (uint256 pAmount, uint256 pUnlock, address pAsset, ) = c.pendingFlashDecision(target, actor);
        assertTrue(pAmount == amount && pAsset == asset, "pre: pending exists");

        // Wait past the unlock time and withdraw.
        vm.warp(block.timestamp + unlockTime + 1);
        vm.prank(actor);
        c.withdrawGovernanceAsset(target, asset);

        // General rule: after withdrawal the pending decision is cleared.
        (uint256 postAmount, uint256 postUnlock, address postAsset, ) = c.pendingFlashDecision(target, actor);
        assertTrue(
            postAmount == 0 && postUnlock == 0 && postAsset == address(0),
            "pending decision must be deleted after withdrawal"
        );
    }
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    receive() external payable {}
    fallback() external payable {}
}
